import org.joda.time.LocalDate;
import org.joda.time.format.DateTimeFormat;
import org.joda.time.format.DateTimeFormatter;
import com.armedia.acm.plugins.consultation.model.Consultation;
import java.util.Date;
import java.util.Calendar;
import org.springframework.expression.EvaluationContext;
import org.springframework.expression.Expression;
import org.springframework.expression.ExpressionParser;
import org.springframework.expression.spel.standard.SpelExpressionParser;
import org.springframework.expression.spel.support.StandardEvaluationContext;
function String dateFormat(String fmt)
{
  return LocalDate.now().toString(DateTimeFormat.forPattern(fmt));
}

function Date addDays(int days)
{
  Calendar cal = Calendar.getInstance();
  cal.add(Calendar.DAY_OF_YEAR, days);
  return cal.getTime();
}

function Boolean evalSpring(String expression, Object obj)
{
    ExpressionParser ep = new SpelExpressionParser();
    Expression exp = ep.parseExpression(expression);
    EvaluationContext ec = new StandardEvaluationContext();

    Boolean evaluated = exp.getValue(ec, obj, Boolean.class);

    return evaluated;
}
// rule values at C22, header at C17
rule "Save Consultation Rules_22"
	salience 65535
	when
		$consultation: Consultation(eval(evalSpring("consultationNumber == null", $consultation)))
	then
		$consultation.setConsultationNumber(dateFormat('yyyyMMdd') + '_' + $consultation.getId());
end

// rule values at C23, header at C17
rule "Save Consultation Rules_23"
	salience 65534
	when
		$consultation: Consultation(eval(evalSpring("container?.folder?.cmisFolderId == null", $consultation)))
	then
		$consultation.setEcmFolderPath('/Sites/acm/documentLibrary/Consultations/' + dateFormat('yyyyMMdd') + '_' + $consultation.getId());
end

// rule values at C24, header at C17
rule "Save Consultation Rules_24"
	salience 65533
	when
		$consultation: Consultation(eval(evalSpring("status == null", $consultation)))
	then
		$consultation.setStatus('DRAFT');
end

// rule values at C25, header at C17
rule "Save Consultation Rules_25"
	salience 65532
	when
		$consultation: Consultation(eval(evalSpring("consultationType == null || consultationType.equals(\"\")", $consultation)))
	then
		$consultation.setConsultationType('Consultation');
end

// rule values at C26, header at C17
rule "Save Consultation Rules_26"
	salience 65531
	when
		$consultation: Consultation(eval(evalSpring("priority == null", $consultation)))
	then
		$consultation.setPriority('Medium');
end

// rule values at C27, header at C17
rule "Save Consultation Rules_27"
	salience 65530
	when
		$consultation: Consultation(eval(evalSpring("dueDate == null", $consultation)))
	then
		$consultation.setDueDate(addDays(180));
